; >S:DUMPER; PUT "DUMPER";; COPIES THE 'SCRBUF' TO THE; SCREEN - GLOPPILY.;FADEIN;LDA MULTI1PHALDA MULTI2PHA;JSR CLSWIN;; CLEAR WINDOW;LDA SNDFLGBEQ NSND1;LDA #%00101111 ;* CHAN#2STA VOL;NSND1;LDA #3STA COUNT;; 4 CHARS TO COPY ACROSS;COP1;LDA #8STA TEMP     ;* LUMINENCE COUNT;JSR RANDOM;LDA RND+1AND #3STA SOU2HI;; RANDOM HI-BIT START;LDA RND+2AND #$80STA SOU2LO;; LO-BIT START AT 0 OR 128;COP4;LDA SOU2LOCLCADC #16STA SOU2LO;LDA SOU2HIADC #0STA SOU2HI;LDA #<$C00STA OLLDA #>$C00STA OL+1;LDA #<SCRBUFSTA DLLDA #>SCRBUFSTA DL+1;LDX COUNTLDA COMPAR,X ;* COPY TABLESTA COPY;LDA COLTBL,X ;* COLOUR OF BLOCKS;LDX TEMPORA LUMIN,X  ; ORA IN BRIGHTNESSSTA COLOUR;LDA MULTI1     ;* AUX COL.1AND #$FORA LUMIN,XSTA MULTI1;LDA MULTI2     ;* AUX COL.2AND #$FORA LUMIN,XSTA MULTI2;LDX #23;COP2;LDY #31;COP3;LDA (DL),Y ;* GET BUFFER COPY;CMP COPY   ;* THE ONE TO COPY ?BNE WRONG  ;* NOT THIS ONE.;STA (OL),Y ;* ONTO SCREEN;LDA OLSTA CL;LDA OL+1SECSBC #4STA CL+1;LDA COLOURSTA (CL),Y ;* PUT A COLOUR ON;WRONG;DEYBPL COP3  ;* FINISH LINE;LDA OLCLCADC #40STA OL;LDA OL+1ADC #0STA OL+1;LDA DLCLCADC #40STA DL;LDA DL+1ADC #0STA DL+1;DEXBPL COP2  ;* ALL THE LINES;LDX DELLY ;* SET UP BEFORE CALLEDJSR DELAY+2;DEC TEMPBMI COPO4;JMP COP4;COPO4;DEC COUNT ;* 4 CHARS TO COPYBMI COPO1;JMP COP1;COPO1;LDA #0STA VOL   ;* SOUND OFF;PLASTA MULTI2;PLASTA MULTI1;RTS;COMPAR;.BYTE 199,198,200,197;COLTBL .BYTE $0F,$0A,$0D,$0C;LUMIN;.BYTE $50.BYTE $70,$60,$50,$40.BYTE $30,$20,$10,$00;; THE FIRST BYTE IS THE LUMINENCE; THAT YOU WANT LEFT ON;.END